/** Fly the missile `steps` at a STATIC target; report the final gap. */
function flyAt(
  start: Vec3,
  vel: Vec3,
  targetPos: Vec3,
  steps: number,
): { pos: Vec3; vel: Vec3 } {
  let pos = { ...start };
  let v = { ...vel };
  for (let i = 0; i < steps; i++) {
    const s = stepMissile(pos, v, targetPos, DT, SPEED, TURN);
    pos = s.pos;
    v = s.vel;
  }
  return { pos, vel: v };
}

