function findRidge(shard: SystemShard, planetId: string, drop = 15): { px: number; pz: number; hM: number; hA: number; hB: number } {
  const h = (x: number, z: number) => shard.terrainHeightAt(planetId, x, z);
  const anchor = planetAnchor(0);
  for (let px = anchor.x - 850; px <= anchor.x + 850; px += 25) {
    for (let pz = anchor.z - 850; pz <= anchor.z + 850; pz += 25) {
      const hA = h(px - 100, pz);
      const hB = h(px + 100, pz);
      const hM = h(px, pz);
      if (hM < hA + drop || hM < hB + drop) continue;
      let occluding = false;
      for (let d = 20; d < 200; d += 20) {
        if (h(px - 97 + d, pz) > hA + 10) {
          occluding = true;
          break;
        }
      }
      if (occluding) return { px, pz, hM, hA, hB };
    }
  }
  throw new Error(`no sweep-occluding ridge found for seed ${SYSTEM_SEED}`);
}

